ALTER TABLE users ADD COLUMN failed_attempts integer NOT NULL DEFAULT 0;ALTER TABLE users ADD COLUMN locked_until timestamptz;ALTER TABLE refresh_tokens ADD COLUMN family_id uuid NOT NULL DEFAULT gen_random_uuid();CREATE INDEX refresh_family ON refresh_tokens(family_id);CREATE TABLE password_reset_tokens(token_hash varchar(64) PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id),expires_at timestamptz NOT NULL,used boolean NOT NULL DEFAULT false);
